#include <vector>
#include <algorithm>

using namespace std;

// Standard tree node structure definition
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class TreeDFSTemplate {
public:
    // Core framework for top-down path generation with explicit backtracking
    vector<vector<int>> pathSum(TreeNode* root, int targetSum) {
        vector<vector<int>> standardPathsList;
        vector<int> pathTracker;

        executePathDFS(root, targetSum, pathTracker, standardPathsList);
        return standardPathsList;
    }

private:
    void executePathDFS(TreeNode* node, int runningTarget, vector<int>& activePath, vector<vector<int>>& totalPaths) {
        if (node == nullptr) {
            return;
        }

        // 1. Incorporate the active element into the path tracker
        activePath.push_back(node->val);

        // 2. Validate target parameters when landing on a terminal leaf node
        if (node->left == nullptr && node->right == nullptr) {
            if (node->val == runningTarget) {
                // Target hit -> serialize a copy of the active path sequence
                totalPaths.push_back(activePath);
            }
        } else {
            // 3. Keep diving down vertical sub-branches, propagating state variables
            executePathDFS(node->left, runningTarget - node->val, activePath, totalPaths);
            executePathDFS(node->right, runningTarget - node->val, activePath, totalPaths);
        }

        // 4. THE BACKTRACKING STEP: Eject the current node before returning up the call stack
        activePath.pop_back();
    }
};

